            "turn and do not modify it afterwards. The controller accepts it only when your session is idle. A blocked verdict "
            "or any unresolved P0/P1 finding ends the run; no second reviewer is launched." + independence)


def combined_status_path(runtime) -> Path:
    return runtime.directory / "automatic-review.json"


def reviewer_status_path(runtime, reviewer_id: str) -> Path:
    """`automatic-review-<id>.json`; the default reviewer's own status lives in the combined file."""
    return runtime.directory / f"automatic-{review_node(reviewer_id)}.json"


class ReviewStatus:
    """The combined review status plus one status per reviewer, persisted together.

    The default reviewer keeps today's single file: its own keys (launch token, session, decision) are
    merged into `automatic-review.json`, whose combined `status` wins. Declared reviewers each get
    `automatic-review-<id>.json` beside the combined file.
    """

    def __init__(self, runtime, combined: dict, statuses: dict):
        self.runtime, self.combined, self.statuses = runtime, combined, statuses
        # Accepted decisions live here until the combined decision persists them (or a deadline/rejection retains them).
        self.decisions: dict = {}

    @property
    def ids(self) -> list[str]:
        return list(self.statuses)

    @classmethod
    def load(cls, runtime) -> "ReviewStatus":
        combined = read_json(combined_status_path(runtime))
        ids = combined.get("reviewers") or reviewer_ids(runtime.plan)
        statuses = {}
        for reviewer_id in ids:
            path = reviewer_status_path(runtime, reviewer_id)
            statuses[reviewer_id] = read_json(path) if path.exists() else {"reviewer_id": reviewer_id, "node_id": review_node(reviewer_id), "status": "pending"}
        return cls(runtime, combined, statuses)

    def save(self) -> None:
        merged = {}
        for reviewer_id, status in self.statuses.items():
            path = reviewer_status_path(self.runtime, reviewer_id)
            if path == combined_status_path(self.runtime):
                merged = status
            else:
                save_json(path, status)
        save_json(combined_status_path(self.runtime), {**merged, **self.combined})

    def record_decisions(self) -> None:
        for reviewer_id, decision in self.decisions.items():
            self.statuses[reviewer_id]["decision"] = decision

    def supersede_running(self) -> None:
        """A reviewer still working when the run is decided is stopped; its status records why nothing waited for it."""
        for status in self.statuses.values():
            if status.get("status") in {"pending", "launching", "running"}:
                status["status"] = "superseded"


def read_review_completion(runtime, reviewer_id: str = DEFAULT_REVIEWER) -> dict:
    """Accept a reviewer's file only when it validates and is bound to this exact run, reviewer, launch, bundle and candidate."""
    from jsonschema.exceptions import ValidationError
    from .verification import validate_schema
    node = review_node(reviewer_id)
    path = runtime.directory / f"{node}.completion.json"
    if path.is_symlink() or not path.is_file() or path.stat().st_size > REVIEW_COMPLETION_LIMIT:
        raise RuntimeError(f"Invalid review completion file ({reviewer_id})")
    try:
        item = read_json(path)
    except ValueError as error:
        raise RuntimeError(f"Malformed review completion signal ({reviewer_id}): {error}") from None
    try:
        validate_schema("reviewCompletion", item)
    except ValidationError as error:
        raise RuntimeError(f"Review completion signal ({reviewer_id}) violates the schema: {error.message}") from None
    status = read_json(reviewer_status_path(runtime, reviewer_id))
    bundle, digest = runtime.validate_bundle()
    if (item["run_id"] != runtime.plan["run_id"] or item["node_id"] != node or item["launch_token"] != status.get("launch_token")
            or item["bundle_sha256"] != digest or item["candidate_commit"] != bundle["candidate_commit"]):
        raise RuntimeError(f"Stale or foreign review completion signal ({reviewer_id})")
    check_finding_lanes(runtime, item["findings"])
    return {"verdict": item["verdict"], "findings": item["findings"]}


def decision_blocks(decision: dict) -> bool:
    """A blocked verdict or an unresolved P0/P1 from any one reviewer blocks the run."""
    from .pipeline import blocking_findings
    return decision["verdict"] != "approved" or bool(blocking_findings(decision["findings"]))


def wait_reviews(runtime, state: ReviewStatus | None = None, *, clock=None, sleep=None) -> dict:
    """Poll every reviewer's receipt. Idle alone never means a verdict; each deadline counts from that reviewer's own launch.

    Returns the accepted decisions by reviewer id (also kept in `state.decisions`) as soon as every reviewer approved,
    or as soon as one accepted file blocks (the others are not waited for). A rejected file, an expired deadline or
    a missing session raises.
    """
    clock = clock or time.time
    sleep = sleep or time.sleep
    validate_automatic(runtime.plan)
    state = state or ReviewStatus.load(runtime)
    timeout = runtime.plan["automatic"]["review_timeout_seconds"]
    started = {}
    for reviewer_id in state.ids:
        receipt = read_json(runtime.directory / f"{review_node(reviewer_id)}.interactive.json")
        started[reviewer_id] = datetime.fromisoformat(receipt["launch_requested_at"]).timestamp()
    decisions = state.decisions
    attention = set()
    while True:
        rows = runtime.sessions.inventory()
        for reviewer_id in state.ids:
            if reviewer_id in decisions:
                continue
            node = review_node(reviewer_id)
            status = state.statuses[reviewer_id]
            if clock() >= started[reviewer_id] + timeout:
                status.update(status="blocked", error="Reviewer deadline exhausted; no second reviewer is launched")
                state.save()
                raise RuntimeError(f"Reviewer {reviewer_id} deadline exhausted; no second reviewer is launched")
            row = runtime.sessions.locate(node, rows)
            if row is None:
                raise RuntimeError(f"Native reviewer {reviewer_id} missing; reconciliation required")
            if row["state"] == "blocked" and reviewer_id not in attention:
                # A native session reports `blocked` when it needs a human: a question or a prompt
                # it cannot answer itself. The operator may answer in the pane; the deadline bounds it.
                attention.add(reviewer_id)
                runtime.event("review", "interactive", f"Reviewer {reviewer_id} needs attention in its pane (native state blocked); waiting until the deadline")
            if row["state"] in {"idle", "done"} and (runtime.directory / f"{node}.completion.json").exists():
                try:
                    decision = read_review_completion(runtime, reviewer_id)
                except RuntimeError as error:
                    status.update(status="blocked", error=str(error))
                    state.save()
                    raise
                decisions[reviewer_id] = decision
                status.update(status="accepted", accepted_at=now())
                state.save()
                if decision_blocks(decision):
                    return decisions  # The first block decides; nobody waits for the other reviewers.
        if set(decisions) == set(state.ids):
            return decisions
        sleep(2)


def review_candidate(runtime) -> dict:
    """Called only by the LangGraph review node. Ambiguous invocations never replay."""
    validate_automatic(runtime.plan)
    bundle, digest = runtime.validate_bundle()
    if combined_status_path(runtime).exists():
        state = ReviewStatus.load(runtime)
        combined = state.combined
        if combined.get("bundle_sha256") == digest and combined.get("status") == "succeeded":
            runtime.validate_review(combined["review"])
            if combined.get("transport") == "native":
                # Accepted earlier, but a stop was not confirmed: retry it (the stop intent makes it idempotent).
                for reviewer_id in state.ids:
                    if not reviewer_stopped(runtime, reviewer_id):
                        runtime.stop_reviewer(reviewer_id)
            return combined["review"]
        if combined.get("bundle_sha256") == digest and combined.get("transport") == "native" and combined.get("status") in {"running", "needs_reconciliation"}:
            # The reviewers kept running while the controller was away: bind what the launches produced, never launch again.
            rebind_reviewers(runtime, state)
            return _accept_native(runtime, bundle, digest, state)
        raise RuntimeError("Prior reviewer invocation needs reconciliation; no automatic relaunch")
    cwd = runtime.directory / "review-worktree"
    if cwd.exists():
        raise RuntimeError("Partial review worktree exists; reconcile rather than overwrite")
    git_worktree(runtime.plan["repository"], "add", "--detach", str(cwd), bundle["candidate_commit"])
    patch = runtime.directory / "review.diff"
    with patch.open("w") as handle:
        subprocess.run(["git", "-C", str(cwd), "diff", "--binary", runtime.plan["base_commit"], bundle["candidate_commit"]], stdout=handle, check=True)
    if reviewer_transport(runtime.plan) == "print":
        return _review_print(runtime, bundle, digest, cwd, patch)
    return _review_native(runtime, bundle, digest, patch)


def rebind_reviewers(runtime, state: ReviewStatus) -> None:
    """Resume: every reviewer receipt is rebound to the one session its launch produced; a reviewer without a receipt

    found = check_run_worktrees(runtime, {*heads, target})
    for path, head in found.items():
        if head != target:
            subprocess.run(["git", "-C", str(path), "-c", "core.hooksPath=/dev/null", "checkout", "-q", "--detach", target], check=True, capture_output=True)
        if git(path, "rev-parse", "HEAD") != target or git(path, "status", "--porcelain"):
            raise RuntimeError(f"Run worktree {path} did not move cleanly to {target}")
    plan["base_commit"] = target
    for node in plan_workers(plan):
        plan["nodes"][node]["observed_start_commit"] = git(Path(plan["nodes"][node]["worktree"]), "rev-parse", "HEAD")
    runtime.event(CHALLENGE, "running", f"Run worktrees moved from base {base} to {target} ({len(found)}); plan.json pins it with the "
                                        "re-pinned files next; no worker exists yet")


def changed_pins(plan: dict, policy: dict) -> list[Path]:
    """The pinned feature files that no longer hold the plan's copies: edited, committed without `resume`, or removed."""
    workers = {worker["node_id"]: worker for worker in policy["workers"]}
    changed = []
    for node in plan_workers(plan):
        path = Path(plan["task_files"][node])
        if not path.is_file() or pinned_task(path.read_text(), workers[node]) != plan["nodes"][node]["task"]:
            changed.append(path)
    decisions = Path(plan["decisions"]["path"])
    if not decisions.is_file() or decisions.read_text() != plan["decisions"]["text"]:
        changed.append(decisions)
    prd = plan.get("prd")
    if prd and (not Path(prd["path"]).is_file() or digest_bytes(Path(prd["path"]).read_bytes()) != prd["sha256"]):
        changed.append(Path(prd["path"]))
    return changed


def refuse_unused_edits(directory: Path, plan: dict, policy: dict) -> None:
    """An override launches the workers on the plan's pinned copies at its base; an unfinished resume, an unused revision or a changed pin refuses it."""
    repo = Path(plan["repository"])
    if (directory / REVISION_INTENT).exists():
        raise ValueError(f"{UNFINISHED_REVISION}; rerun resume without --accept-challenge to finish it")
    pending = [commit for commit in commits_after(repo, plan["base_commit"]) or [] if is_revision(repo, commit, plan)]
    if pending:
        raise ValueError(f"An interrupted resume committed revised feature files ({', '.join(pending)}) that this run does not use yet; "
                         "rerun resume without --accept-challenge to finish moving the run to them")
    edited = {path for path in dirty_paths(repo) if path in pinned_paths(plan)}
    edited |= {path.relative_to(repo).as_posix() if path.is_relative_to(repo) else str(path) for path in changed_pins(plan, policy)}
    if edited:
        raise ValueError(f"Feature files changed since they were pinned ({', '.join(sorted(edited))}); the override would launch the workers "
                         "without them. Rerun resume without --accept-challenge to commit them and rerun the challenge, or revert them")


def launched_workers(directory: Path, plan: dict) -> list[str]:
    """Lanes with a launch receipt, which InteractiveSessions saves before `claude --bg`. `<lane>.json` is none: only the
    legacy print workers write it, and a lane may share its name with a run file (plan.json, policy.json, terminals.json)."""
    return [node for node in plan_workers(plan) if (directory / f"{node}.interactive.json").exists()]


def resume_challenge(runtime, accept_reason: str | None = None) -> dict:
    """`resume`: rerun the challenge on the re-pinned feature files as the next attempt, or record `accepted` with a reason.

    Only before any worker launch. Edited feature files are committed on the run's branch first and the run moves to
    that commit, so the source checkout stays clean for integration. A challenge that already passed or was accepted
    is returned as it is. The override accepts only an attempt that read what the plan pins now: a rerun that failed
    after its re-pin leaves the paused record of the previous attempt, which read other files.
    """
    directory, plan = runtime.directory, runtime.plan
    if not has_challenge(plan):
        raise ValueError("This run has no design challenge to resume (feature.json before 2.2.0, or challenge: false)")
    launched = launched_workers(directory, plan)
    if launched:
        raise ValueError(f"Workers already launched ({', '.join(launched)}); resume applies only before any worker starts")
    current = load_challenge(directory)
    if current is not None and current["status"] in {"passed", "accepted"}:
        return current
    if accept_reason is not None:
        if not accept_reason.strip():
            raise ValueError("--accept-challenge needs a non-empty reason")
        if current is None or current["status"] != "paused":
            raise ValueError("Only a paused design challenge can be accepted")
        refuse_unused_edits(directory, plan, runtime.policy)
        changed = [key.removesuffix("_sha256") for key, value in pinned_digests(directory, plan).items() if current["pinned"].get(key) != value]
        if changed:
            raise ValueError(f"Design challenge attempt {current['attempt']} read other feature files than the plan now pins ({', '.join(changed)}): "
                             "a later resume re-pinned them and its challenge decided nothing. The override would launch the workers on "
                             "files no challenge read; rerun resume without --accept-challenge")
        record = {**current, "status": "accepted", "accepted_reason": accept_reason.strip(), "decided_at": now()}
        save_challenge(directory, record)
        runtime.event(CHALLENGE, "succeeded", f"Design challenge attempt {record['attempt']} accepted by the operator: {record['accepted_reason']}")
        return record
    running = directory / "challenge.running.json"
    attempt = max(current["attempt"] if current else 0, read_json(running)["attempt"] if running.exists() else 0) + 1
    read_pinned(plan)  # A brief that lost a required section is refused before anything is committed.
    commit_revision(runtime, attempt - 1)
    repin(directory, plan, runtime.policy)  # The moved base and the re-pinned files in one plan.json write.
    (directory / REVISION_INTENT).unlink()
    runtime.event(CHALLENGE, "running", f"Feature files re-pinned for design challenge attempt {attempt} on base {plan['base_commit']}")
    return run_challenge(runtime, attempt)


# ---- Worker questions and the persisted deadline pause ---------------------------------------------------------

def iso(timestamp: float) -> str:
    return datetime.fromtimestamp(timestamp, timezone.utc).isoformat().replace("+00:00", "Z")


def epoch(value: str) -> float:
    return datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp()


@contextmanager
def question_lock(directory: Path):
    """Serialises the controller and `answer` over `<node>.questions.json` and `<node>.deadline.json`."""
    with (directory / "questions.lock").open("a") as handle:
        fcntl.flock(handle, fcntl.LOCK_EX)
        try:
            yield
        finally:
            fcntl.flock(handle, fcntl.LOCK_UN)


def load_questions(directory: Path, node: str) -> list[dict]:
    path = directory / f"{node}.questions.json"
    return read_json(path)["questions"] if path.exists() else []


def save_questions(directory: Path, node: str, questions: list[dict]) -> None:
    save_json(directory / f"{node}.questions.json", {"node_id": node, "questions": questions})


def waiting_question(directory: Path, node: str) -> dict | None:
    questions = load_questions(directory, node)
    return questions[-1] if questions and questions[-1]["answer"] is None else None


def load_deadline(directory: Path, node: str) -> dict:
    path = directory / f"{node}.deadline.json"
    return read_json(path) if path.exists() else {"node_id": node, "paused_seconds": 0.0, "paused_at": None}


def deadline_extension(directory: Path, node: str) -> float | None:
    """Seconds the worker's deadline moved by answered questions; None while a question waits (no deadline runs)."""
    deadline = load_deadline(directory, node)
    return None if deadline["paused_at"] else float(deadline["paused_seconds"])


def deadline_met(directory: Path, node: str) -> bool:
    """Whether the controller accepted the lane's completion signal once its turn ended (`met_at`): its deadline is met for good."""
    return bool(load_deadline(directory, node).get("met_at"))


def mark_deadline_met(directory: Path, node: str, at: float) -> None:
    """Record, once, that the lane's completion signal met its deadline while other lanes still work."""
    with question_lock(directory):
        deadline = load_deadline(directory, node)
        if not deadline.get("met_at"):
            save_json(directory / f"{node}.deadline.json", {**deadline, "met_at": iso(at)})


def resume_deadline(directory: Path, node: str, at: float) -> None:
    deadline = load_deadline(directory, node)
    if deadline["paused_at"]:
        deadline["paused_seconds"] = float(deadline["paused_seconds"]) + max(0.0, at - epoch(deadline["paused_at"]))
        deadline["paused_at"] = None
        save_json(directory / f"{node}.deadline.json", deadline)


def record_question(runtime, node: str, item: dict, clock=None) -> dict:
    """A `question` completion: kept as `<node>.question-<n>.json`, listed, and the lane's deadline paused. A fourth blocks."""
    directory = runtime.directory
    with question_lock(directory):
        questions = load_questions(directory, node)
        number = len(questions) + 1
        if number > MAX_QUESTIONS:
            raise RuntimeError(f"Worker {node} asked question {number}; at most {MAX_QUESTIONS} are answered, so it is treated as blocked: "
                               f"{item['question']}")
        at = (clock or time.time)()
        os.replace(directory / f"{node}.completion.json", directory / f"{node}.question-{number}.json")
        entry = {"n": number, "question": item["question"], "asked_at": iso(at), "answer": None, "answered_at": None}
        save_questions(directory, node, [*questions, entry])
        deadline = load_deadline(directory, node)
        deadline["paused_at"] = iso(at)
        save_json(directory / f"{node}.deadline.json", deadline)
    runtime.event(node, "interactive", f"Worker {node} asked question {number} of {MAX_QUESTIONS}; its deadline is paused until "
                                       f"`python -m workflow answer {directory} {node} \"<text>\"`: {item['question']}")
    return entry


# What the controller records when the session works again while its question waits: the operator typed in the pane,
# or something else woke the session (a background command it started ending). It never claims an answer.
PANE_ANSWER = "(no answer recorded: the worker's session worked again in its pane)"


def went_on(directory: Path, node: str) -> str | None:
    """What shows the worker went on from its latest question, or None: record_question moved that question's file away,
    so a completion file is its next signal; a saved handoff or a stop follows one. A stopped worker's pane is a shell."""
    for name, reason in (("stop", "stopped by the controller"), ("handoff", "its handoff saved"), ("completion", "its next completion signal written")):
        if (directory / f"{node}.{name}.json").exists():
            return reason
    return None


def record_answer(directory: Path, node: str, text: str, clock=None, delivered: bool | None = None) -> dict:
    """The latest question's answer; the deadline restarts now. Refused when no question waits.

    `answer` records `delivered: false` and sets it once the text reached the worker, so a failed delivery can be
    retried. It also replaces PANE_ANSWER, which the controller records (without the flag) once the session works

class InteractiveSessions(ClaudeSessions):
    """Native Claude background sessions, not print-mode jobs or Herdr-owned agents."""

    def inventory(self) -> list[dict]:
        """`claude agents --json`. The listing only reads, so while the background service restarts (it exits nonzero,
        prints no list or hangs) it is asked again for the grace; a listing that stays unavailable is TransientInfraError.
        """
        try:
            response = run_claude([self.executable, "agents", "--json"], capture_output=True, text=True, timeout=15,
                                  retry_output=lambda result: listed_rows(result) is None)
        except subprocess.TimeoutExpired as error:
            raise TransientInfraError(f"Claude session inventory unavailable for {CLAUDE_MISSING_GRACE_SECONDS}s: {error}") from error
        rows = listed_rows(response)
        if rows is None:
            # Claude Code is unavailable, which says nothing about any session.
            answer = f"exited {response.returncode}" if response.returncode else "printed no session list"
            detail = ((response.stderr or "").strip() or (response.stdout or "").strip())[-300:]
            raise TransientInfraError(f"Claude session inventory unavailable for {CLAUDE_MISSING_GRACE_SECONDS}s: "
                                      f"`claude agents --json` {answer}" + (f": {detail}" if detail else ""))
        return rows

    def launch_name(self, node: str) -> str:
        """`workflow-<run>-<lane>`, `workflow-<run>-reviewer` for the default reviewer, `workflow-<run>-reviewer-<id>` otherwise."""
        if node == REVIEW:
            return f"workflow-{self.plan['run_id']}-reviewer"
        if node.startswith("review-"):
            return f"workflow-{self.plan['run_id']}-reviewer-{node[len('review-'):]}"
        return f"workflow-{self.plan['run_id']}-{node}"

    def node_worktree(self, node: str) -> Path:
        """Workers live in the plan's worktrees; every reviewer in the run's shared candidate checkout."""
        if is_review_node(node):
            return self.directory / "review-worktree"
        return Path(self.plan["nodes"][node]["worktree"])

    def locate(self, node: str, rows: list[dict]) -> dict | None:
        path = self.directory / f"{node}.interactive.json"
        if not path.exists():
            return None
        receipt = read_json(path)
        if receipt["plan_digest"] != plan_digest(self.plan):
            raise RuntimeError("Plan changed; cannot reconcile session")
        background_id = receipt.get("background_id")
        if not background_id:
            log = self.directory / f"{node}.launch.log"
            if not log.exists():
                return None
            # --bg assigns its own UUID. Bind the ID printed by this launch;
            # never adopt a guessed UUID or a name-only match.
            ids = set(re.findall(r"claude attach ([a-f0-9-]{8,36})\s", log.read_text(errors="replace")))
            if len(ids) != 1:
                raise RuntimeError("Missing/ambiguous native launch ID; reconcile manually")
            background_id = ids.pop()
        matches = [row for row in rows if row.get("id") == background_id]
        if not matches:
            return None
        if len(matches) != 1:
            raise RuntimeError("Ambiguous Claude session identity")
        row = matches[0]

workers = lanes(runtime)
if any((runtime.directory / f"{node}.stop.json").exists() for node in workers):
    # Recover a controller crash after durable handoffs/stop intent, before snapshot.
    for node in workers:
        if read_completion(runtime, node) != read_json(runtime.directory / f"{node}.handoff.json"):
            raise RuntimeError("Handoff changed after stop intent")
    return
attention: set[str] = set()
# Lanes whose completion signal was accepted once their turn ended: their deadline is met, whatever their session
# does afterwards (an operator prompt in its pane, a command of its own). Kept across controller restarts.
met = {node for node in workers if deadline_met(runtime.directory, node)}
bounds: dict[str, float] = {}  # The latest lane deadline last announced for a met lane that is out again.
# Answers recorded before this controller started need no second event.
answered = {(node, entry["n"]) for node in workers for entry in load_questions(runtime.directory, node) if entry["answer"] is not None}
while True:
    rows = runtime.sessions.inventory()
    handoffs = {}
    for node in workers:
        row = runtime.sessions.locate(node, rows)
        if row is None:
            raise RuntimeError("Native worker missing; reconciliation required")
        path = runtime.directory / f"{node}.completion.json"
        # The turn is over, so the file is final. A turn that ends on a question reports idle, done or, waiting on
        # the operator, blocked; a `completed` or `blocked` file is still accepted only once idle or done, as before.
        item = read_signal(runtime, node) if row["state"] in {"idle", "done", "blocked"} and path.exists() else None
        waiting = waiting_question(runtime.directory, node)
        if waiting and (row["state"] == "working" or item):
            # Working again while the question waits: its deadline runs again. A reply typed in the pane may never show
            # `working` (the registry can report the whole reply turn as blocked, or keep done), so the next completion
            # signal proves it too, before it is recorded or accepted. `answer` may have landed meanwhile (then nothing
            # is recorded); until that next signal it still records and delivers an answer.
            record_pane_answer(runtime.directory, node, clock)
            waiting = None
        for entry in load_questions(runtime.directory, node):
            if entry["answer"] is not None and (node, entry["n"]) not in answered:
                answered.add((node, entry["n"]))
                if entry["answer"] != PANE_ANSWER:
                    message = f"Worker {node} question {entry['n']} answered; its deadline runs again"
                elif item:
                    message = (f"Worker {node} wrote its next completion signal while question {entry['n']} waited: it worked again (an "
                               "answer typed in its pane, or a command of its own) though no poll saw it working. Its deadline runs "
                               f"again, and `answer` is refused for question {entry['n']}")
                else:
                    message = (f"Worker {node} is working again while question {entry['n']} waits (an answer typed in its pane, or a "
                               "command of its own); its deadline runs again, and `answer` still records and delivers an answer "
                               "until the worker writes its next completion signal")
                runtime.event(node, "interactive", message)
        if item and item["status"] != "question" and row["state"] != "blocked":
            handoffs[node] = read_completion(runtime, node)
            continue  # Its completion signal met the deadline.
        deadline = lane_deadline(runtime, node)  # None while a question waits: that lane has no running deadline.
        if node in met:
            # Its signal met its deadline: it never ends the run while another lane works or waits on a question. Once
            # every lane's signal was accepted that protects no lane, so the latest lane deadline bounds its session
            # working or blocked again: it never makes the run wait longer than the lanes' own deadlines would have.
            deadline = latest_deadline(runtime, workers) if deadline is not None and met == set(workers) else None
        if item and item["status"] == "question":
            # Written before the deadline, it pauses it from then, though first read after it (the controller away).
            asked = question_asked_at(runtime, node, clock())
            if deadline is None or asked < deadline:
                record_question(runtime, node, item, lambda: asked)
                continue
        if node in met and deadline is not None and bounds.get(node) != deadline:
            bounds[node] = deadline
            runtime.event(node, "interactive", f"Worker {node} is {row['state']} again after its completion signal was accepted, and so was "
                                               f"every other lane's: the run waits for its turn to end until {iso(deadline)}, the latest lane deadline")
        if deadline is not None and clock() >= deadline:
            raise RuntimeError(f"Worker {node} deadline exhausted; no automatic relaunch")
        if row["state"] == "blocked" and not waiting and node not in attention:
            # A native session reports `blocked` when its turn ended needing a human: a question,
            # a permission prompt or a refusal the harness could not continue past. That is not a
            # failure of the lane, and the other lanes keep working. The operator may answer in the
            # pane; the worker deadline bounds the wait (a met lane's, as above). No billing/provider
            # fallback. A recorded question already said what it waits for, and its deadline is paused.
            attention.add(node)
            runtime.event(node, "interactive", f"Worker {node} needs attention in its pane (native state blocked); " + (
                "its completion signal met its deadline, so the run waits for it while another lane works or waits on a question, "
                "then until the latest lane deadline" if node in met else "waiting until its deadline"))
        elif row["state"] != "blocked":
            attention.discard(node)
    if set(handoffs) == set(workers):
        for node, value in handoffs.items():
            save_json(runtime.directory / f"{node}.handoff.json", value)
        return
    for node in set(handoffs) - met:
        mark_deadline_met(runtime.directory, node, clock())
